using System;
using System.Collections.Generic;
using UnityEngine;

namespace WorkingVehicles
{
    /// <summary>
    /// Drawing of the mod's panels in the visual language of The Long Dark, with colors sampled from the game's own screens
    /// (inventory, item details, pause menu): flat near-black panels and tiles without borders or rounded corners,
    /// a petrol-blue gradient for the selected tile, white / grey tracked upper-case text, amber and red only for wear and danger,
    /// dark flat buttons and prompts without boxes.
    /// Everything is generated by code (no files).
    /// </summary>
    internal static class Ui
    {
        // ---- palette sampled from the game (RGB 0-255 in the comments)
        public static readonly Color White = C(250, 250, 250);        // titles, selected text, numbers
        static readonly Color Light = C(200, 200, 200);               // descriptions
        public static readonly Color Gray = C(122, 122, 122);         // unselected / secondary text
        public static readonly Color Accent = C(3, 153, 229);         // blue of the "rare" label: neutral highlight
        public static readonly Color Green = C(0, 206, 132);          // positive values (+5.00)
        public static readonly Color Yellow = C(231, 178, 78);        // worn (star at 20-45 %)
        public static readonly Color Red = C(155, 64, 69);            // critical (star at 8 %)
        public static readonly Color Sage = C(110, 136, 125);         // good-condition bar (sampled from the engine screen)
        public static readonly Color Amber = C(221, 179, 103);        // worn bar / value
        public static readonly Color Backdrop = new Color(10f / 255f, 11f / 255f, 11f / 255f, 0.93f);   // panel background
        static readonly Color Tile = new Color(0f, 0f, 0f, 0.62f);                                      // inventory tile
        static readonly Color Button = new Color(3f / 255f, 3f / 255f, 3f / 255f, 0.86f);               // SOLTAR / ATRÁS
        static readonly Color InfoBar = new Color(22f / 255f, 26f / 255f, 26f / 255f, 0.92f);           // bar with condition and weight
        static readonly Color Hair = new Color(1f, 1f, 1f, 0.11f);

        static readonly Color TrackColor = C(34, 39, 43);
        static readonly Color Sep = C(40, 46, 48);

        static Color C(int r, int g, int b) { return new Color(r / 255f, g / 255f, b / 255f, 1f); }

        static GUIStyle est;
        static Font font;
        static bool fontTried;
        static Texture2D band, selTex, fadeTex;
        static Texture2D icons, frame, paint;        // embedded art: part icons, painted panel frame, rough strip for bars and buttons
        static bool artTried;
        static readonly Dictionary<long, float> glyph = new Dictionary<long, float>();

        public static float Sc { get { return Mathf.Clamp(Screen.height / 1080f, 0.7f, 2f); } }

        public static void Start()
        {
            if (est == null)
            {
                est = new GUIStyle(GUI.skin.label);
                est.wordWrap = false;
                est.clipping = TextClipping.Overflow;
                est.richText = false;
            }
            if (!fontTried)
            {
                fontTried = true;
                // The game's font is a wide-tracked geometric sans; the closest installed ones first, Unity's default as a fallback.
                foreach (string n in new[] { "Bahnschrift", "Segoe UI Semibold", "Segoe UI", "Trebuchet MS" })
                {
                    try
                    {
                        Font f = Font.CreateDynamicFontFromOSFont(n, 32);
                        if (f != null) { font = f; break; }
                    }
                    catch (Exception) { }
                }
            }
            if (font != null) est.font = font;
            if (band == null) band = MakeBand();
            if (selTex == null) selTex = MakeSelected();
            if (fadeTex == null) fadeTex = MakeFade();
            if (!artTried)
            {
                artTried = true;
                icons = LoadArt("ui_icons.png");
                frame = LoadArt("ui_frame.png");
                paint = LoadArt("ui_paint.png");
                iconTex = Slice(icons, new[] { 0, 128, 256, 384, 512 }, new[] { 0, 128, 256 });
                // the slice order is row by row: 0-3 first row, 4-7 second row: it matches the icon numbers
                frameTex = Slice(frame, new[] { 0, 72, 568, 640 }, new[] { 0, 72, 628, 700 });
                paintTex = Slice(paint, new[] { 0, 12, 244, 256 }, new[] { 0, 32 });
                if (frameTex == null) frame = null;
                MelonLoader.MelonLogger.Msg("[Ui] art: icons " + (iconTex != null ? iconTex.Length : 0) + ", frame " + (frameTex != null ? frameTex.Length : 0) + ", paint " + (paintTex != null ? paintTex.Length : 0));
            }
        }

        static Texture2D LoadArt(string file)
        {
            try
            {
                using (System.IO.Stream st = System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("WorkingVehicles." + file))
                {
                    if (st == null) return null;
                    var ms = new System.IO.MemoryStream();
                    st.CopyTo(ms);
                    var t = new Texture2D(2, 2, TextureFormat.RGBA32, false);
                    if (!ImageConversion.LoadImage(t, ms.ToArray())) return null;
                    t.wrapMode = TextureWrapMode.Clamp;
                    t.filterMode = FilterMode.Bilinear;
                    t.hideFlags = HideFlags.DontUnloadUnusedAsset;
                    return t;
                }
            }
            catch (Exception) { return null; }
        }

        // The pieces are cut once into their own small textures, so they are drawn with GUI.DrawTexture only
        // (the same call the rest of the mod uses).
        static Texture2D[] iconTex, frameTex, paintTex;

        static Texture2D Cut(Color32[] all, int W, int x, int y, int w, int h)
        {
            var px = new Color32[w * h];
            for (int j = 0; j < h; j++)
                for (int i = 0; i < w; i++)
                    px[j * w + i] = all[(y + j) * W + x + i];
            var t = new Texture2D(w, h, TextureFormat.RGBA32, false);
            t.SetPixels32(px);
            t.wrapMode = TextureWrapMode.Clamp;
            t.filterMode = FilterMode.Bilinear;
            t.Apply();
            t.hideFlags = HideFlags.DontUnloadUnusedAsset;
            return t;
        }

        // y is counted from the TOP of the image (Texture2D pixels start at the bottom).
        static Texture2D[] Slice(Texture2D src, int[] xs, int[] ys)
        {
            if (src == null) return null;
            try
            {
                int W = src.width, H = src.height;
                Color32[] all = src.GetPixels32();
                var list = new List<Texture2D>();
                for (int j = 0; j + 1 < ys.Length; j++)
                    for (int i = 0; i + 1 < xs.Length; i++)
                        list.Add(Cut(all, W, xs[i], H - ys[j + 1], xs[i + 1] - xs[i], ys[j + 1] - ys[j]));
                return list.ToArray();
            }
            catch (Exception e)
            {
                MelonLoader.MelonLogger.Warning("[Ui] could not cut the art: " + e.Message);
                return null;
            }
        }

        /// <summary>Part icon (0 battery, 1 alternator, 2 spark plugs, 3 ignition wires, 4 valve cover, 5 cylinder head, 6 head gasket, 7 engine).</summary>
        public static void Icon(Rect r, int i, Color c)
        {
            if (iconTex == null || i < 0 || i >= iconTex.Length) return;
            Tex(r, iconTex[i], c);
        }

        /// <summary>Rough painted strip (bars, buttons): ends and edges are a little ragged, like the game's brush-made widgets.</summary>
        public static void Paint(Rect r, Color c)
        {
            if (paintTex == null) { Fill(r, c); return; }
            float cap = Mathf.Min(r.height * 0.9f, r.width * 0.5f);
            Tex(new Rect(r.x, r.y, cap, r.height), paintTex[0], c);
            Tex(new Rect(r.x + cap, r.y, r.width - 2f * cap, r.height), paintTex[1], c);
            Tex(new Rect(r.xMax - cap, r.y, cap, r.height), paintTex[2], c);
        }

        // 9-slice of the painted frame (640 x 700 reference image, 72 px slices).
        static void Frame(Rect r)
        {
            float k = r.width / 640f;
            float sx = Mathf.Min(72f * k, r.width * 0.5f - 1f), sy = Mathf.Min(72f * k, r.height * 0.5f - 1f);
            float[] xs = { r.x, r.x + sx, r.xMax - sx, r.xMax };
            float[] ys = { r.y, r.y + sy, r.yMax - sy, r.yMax };
            for (int j = 0; j < 3; j++)
                for (int i = 0; i < 3; i++)
                    Tex(new Rect(xs[i], ys[j], xs[i + 1] - xs[i], ys[j + 1] - ys[j]), frameTex[j * 3 + i], Color.white);
        }

        // ------------------------------------------------------------------ generated textures

        // horizontal strip: transparent at both ends, solid in the middle (soft band behind on-screen text)
        static Texture2D MakeBand()
        {
            const int n = 128;
            var t = new Texture2D(n, 1, TextureFormat.RGBA32, false);
            for (int x = 0; x < n; x++)
            {
                float u = (x + 0.5f) / n;
                float a = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(Mathf.Min(u, 1f - u) / 0.40f));
                t.SetPixel(x, 0, new Color(1f, 1f, 1f, a));
            }
            Finish(t);
            return t;
        }

        // the selected inventory tile: petrol blue, brighter in the middle (0,38,57) -> (0,63,94) -> (0,39,59)
        static Texture2D MakeSelected()
        {
            const int n = 48;
            var t = new Texture2D(1, n, TextureFormat.RGBA32, false);
            Color a = C(0, 38, 57), b = C(0, 63, 94), c = C(0, 39, 59);
            for (int y = 0; y < n; y++)
            {
                float u = (y + 0.5f) / n;           // 0 = bottom, 1 = top
                float k = 1f - Mathf.Abs(u - 0.58f) / 0.58f;
                Color col = Color.Lerp(u > 0.58f ? a : c, b, Mathf.Clamp01(k));
                t.SetPixel(0, y, col);
            }
            Finish(t);
            return t;
        }

        // vertical fade: solid at the top, transparent at the bottom (light vignette on the panels)
        static Texture2D MakeFade()
        {
            const int n = 64;
            var t = new Texture2D(1, n, TextureFormat.RGBA32, false);
            for (int y = 0; y < n; y++)
            {
                float u = (y + 0.5f) / n;
                t.SetPixel(0, y, new Color(1f, 1f, 1f, u * u));
            }
            Finish(t);
            return t;
        }

        static void Finish(Texture2D t)
        {
            t.Apply();
            t.wrapMode = TextureWrapMode.Clamp;
            t.filterMode = FilterMode.Bilinear;
            t.hideFlags = HideFlags.DontUnloadUnusedAsset;
        }

        // ------------------------------------------------------------------ primitives

        static Rect Snap(Rect r)
        {
            return new Rect(Mathf.Round(r.x), Mathf.Round(r.y), Mathf.Max(1f, Mathf.Round(r.width)), Mathf.Max(1f, Mathf.Round(r.height)));
        }

        /// <summary>Solid rectangle.</summary>
        public static void Fill(Rect r, Color c)
        {
            Color g0 = GUI.color;
            GUI.color = c;
            GUI.DrawTexture(Snap(r), Texture2D.whiteTexture);
            GUI.color = g0;
        }

        static void Tex(Rect r, Texture2D t, Color c)
        {
            if (t == null) return;
            Color g0 = GUI.color;
            GUI.color = c;
            GUI.DrawTexture(Snap(r), t);
            GUI.color = g0;
        }

        // ------------------------------------------------------------------ text (tracked, like the game's)

        static void Setup(float size, bool bold)
        {
            est.fontSize = Mathf.Max(8, Mathf.RoundToInt(size * Sc));
            est.fontStyle = bold ? FontStyle.Bold : FontStyle.Normal;
            est.alignment = TextAnchor.MiddleLeft;
        }

        // One cached string per character: drawing the text letter by letter no longer allocates a string per letter per frame.
        static readonly Dictionary<char, string> charText = new Dictionary<char, string>();
        static string CharText(char ch)
        {
            string t;
            if (!charText.TryGetValue(ch, out t)) { t = ch.ToString(); charText[ch] = t; }
            return t;
        }

        public static string Upper(string s) { return string.IsNullOrEmpty(s) ? s : s.ToUpperInvariant(); }

        static bool IsCaps(string s)
        {
            bool any = false;
            foreach (char ch in s)
            {
                if (char.IsLetter(ch)) { any = true; if (char.IsLower(ch)) return false; }
            }
            return any;
        }

        // Extra space between letters: wide for upper-case labels, light for sentences (as in the game).
        static float Tracking(string s, float size)
        {
            return size * Sc * (IsCaps(s) ? 0.10f : 0.035f);
        }

        static float GlyphWidth(char ch, int fontSize, bool bold)
        {
            long key = ((long)ch << 20) | ((long)fontSize << 1) | (bold ? 1L : 0L);
            float w;
            if (glyph.TryGetValue(key, out w)) return w;
            w = est.CalcSize(new GUIContent(ch == ' ' ? "i i" : ch.ToString())).x;
            if (ch == ' ') w = Mathf.Max(est.fontSize * 0.28f, w - 2f * est.CalcSize(new GUIContent("i")).x);
            if (glyph.Count > 4000) glyph.Clear();
            glyph[key] = w;
            return w;
        }

        /// <summary>Width of the text with the font and tracking in use.</summary>
        static float Width(string s, float size, bool bold)
        {
            if (est == null || string.IsNullOrEmpty(s)) return 0f;
            Setup(size, bold);
            float tr = Tracking(s, size), w = 0f;
            foreach (char ch in s) w += GlyphWidth(ch, est.fontSize, bold) + tr;
            return w - tr;
        }

        public static void Text(Rect r, string s, float size, Color c, TextAnchor toward, bool bold)
        {
            if (est == null || string.IsNullOrEmpty(s)) return;
            if (s.IndexOf('\n') >= 0)
            {
                string[] ls = s.Split('\n');
                float lh = size * Sc * 1.4f;
                float top = r.y + (r.height - lh * ls.Length) * 0.5f;
                for (int i = 0; i < ls.Length; i++) Text(new Rect(r.x, top + i * lh, r.width, lh), ls[i], size, c, toward, bold);
                return;
            }
            Setup(size, bold);
            float e = Sc;
            float tr = Tracking(s, size);
            float total = Width(s, size, bold);
            float x = r.x;
            if (toward == TextAnchor.MiddleRight || toward == TextAnchor.UpperRight || toward == TextAnchor.LowerRight) x = r.xMax - total;
            else if (toward == TextAnchor.MiddleCenter || toward == TextAnchor.UpperCenter || toward == TextAnchor.LowerCenter) x = r.x + (r.width - total) * 0.5f;
            Color shadow = new Color(0f, 0f, 0f, 0.75f * c.a);
            foreach (char ch in s)
            {
                float gw = GlyphWidth(ch, est.fontSize, bold);
                if (ch != ' ')
                {
                    Rect cell = new Rect(x, r.y, gw + 6f, r.height);
                    est.normal.textColor = shadow;
                    GUI.Label(new Rect(cell.x + 1.3f * e, cell.y + 1.3f * e, cell.width, cell.height), CharText(ch), est);
                    est.normal.textColor = c;
                    GUI.Label(cell, CharText(ch), est);
                }
                x += gw + tr;
            }
        }

        // ------------------------------------------------------------------ bars

        static Color BarColor(Color c)
        {
            // the game draws good condition in white; amber / red only when it is worn or critical
            if (c == Green) return Sage;
            if (c == Yellow) return Amber;
            return c;
        }

        /// <summary>Thin bar on a dark track.</summary>
        public static void Bar(Rect r, float frac, Color c)
        {
            Paint(r, TrackColor);
            float w = r.width * Mathf.Clamp01(frac);
            if (frac > 0.003f) Paint(new Rect(r.x, r.y, Mathf.Max(r.height, w), r.height), BarColor(c));
        }

        // ------------------------------------------------------------------ panel

        /// <summary>Panel with the painted frame of the game's screens: rough light rim, near-black body, optional part icon, tracked
        /// upper-case title, a status line and a hairline under the header. Returns the usable rectangle (below the header).</summary>
        public static Rect Panel(Rect r, string title, string subtitle, Color accent) { return Panel(r, title, subtitle, accent, -1); }

        public static Rect Panel(Rect r, string title, string subtitle, Color accent, int icon)
        {
            float k = r.width / 640f;
            if (frame != null) Frame(r);
            else
            {
                Fill(r, Backdrop);
                Tex(new Rect(r.x, r.y, r.width, Mathf.Min(r.height, 170f * k)), fadeTex, new Color(1f, 1f, 1f, 0.035f));
            }

            bool withIcon = icon >= 0 && iconTex != null;
            float tx = r.x + (withIcon ? 143f : 44f) * k;
            if (withIcon) Icon(new Rect(r.x + 44f * k - 10f * k, r.y + 61f * k - 36f * k, 72f * k, 72f * k), icon, Color.white);
            float ty = withIcon ? 53f : (string.IsNullOrEmpty(subtitle) ? 50f : 46f);
            Text(new Rect(tx, r.y + (ty - 20f) * k, r.width - (tx - r.x) - 30f * k, 40f * k), Upper(title), Fit(30f, k), White, TextAnchor.MiddleLeft, false);
            float line = withIcon ? 125f : 98f;
            if (!string.IsNullOrEmpty(subtitle))
            {
                Color sc = accent == Red ? Color.Lerp(Light, Red, 0.55f) : accent == Yellow ? Color.Lerp(Light, Yellow, 0.6f) : Light;
                Text(new Rect(tx, r.y + (withIcon ? 83f : 78f) * k - 14f * k, r.width - (tx - r.x) - 30f * k, 28f * k), subtitle, Fit(17f, k), sc, TextAnchor.MiddleLeft, false);
            }
            else line = 78f;
            Fill(new Rect(r.x + 36f * k, r.y + line * k, r.width - 72f * k, Mathf.Max(1f, Sc)), Sep);
            return new Rect(r.x + 36f * k, r.y + line * k + 1f, r.width - 72f * k, r.height - line * k - 24f * k);
        }

        // font size in "reference" units that ends up at k times the size at the current resolution
        static float Fit(float size, float k) { return size * k / Sc; }

        /// <summary>A menu row: name on the left, value on the right and, if requested, a thin painted bar. A hairline separates the rows;
        /// the selected row uses the game's petrol-blue selection tile.</summary>
        public static void Row(Rect r, string names, string value, Color colValue, bool sel, float bar, Color colBar)
        {
            float e = Sc;
            Rect tile = new Rect(r.x, r.y + 1f, r.width, r.height - 2f);
            if (sel) Tex(tile, selTex, Color.white);
            else Fill(new Rect(r.x, r.yMax - Mathf.Max(1f, e), r.width, Mathf.Max(1f, e)), Sep);

            bool withBar = bar >= 0f;
            float heightText = withBar ? r.height * 0.64f : r.height;
            Text(new Rect(tile.x + 20f * e, r.y, r.width * 0.60f, heightText), names, 20f, sel ? White : Light, TextAnchor.MiddleLeft, sel);
            float vw = 0f;
            if (!string.IsNullOrEmpty(value))
            {
                vw = Width(value, 17f, false);
                Text(new Rect(tile.xMax - 20f * e - r.width * 0.5f, r.y, r.width * 0.5f, heightText), value, 17f, colValue == Green ? White : colValue, TextAnchor.MiddleRight, false);
            }
            if (withBar) Bar(new Rect(tile.x + 20f * e, r.y + r.height * 0.74f, tile.width - 40f * e, 8f * e), bar, colBar);
        }

        /// <summary>Row of the engine screen: part icon, name, painted bar and condition ("86%", or "36%  WORN" in amber).
        /// 'row' is expected to be 60 units tall at scale k.</summary>
        public static void IconRow(Rect row, float k, int icon, string name, string value, string tag, Color colValue, Color colTag, bool sel, float frac, Color colBar)
        {
            float e = Sc;
            if (sel) Tex(new Rect(row.x, row.y + 1f, row.width, row.height - 2f), selTex, Color.white);
            else
            {
                Fill(new Rect(row.x, row.y + 1f, 80f * k, row.height - 2f), new Color(1f, 1f, 1f, 0.035f));
                Fill(new Rect(row.x, row.yMax - Mathf.Max(1f, e), row.width, Mathf.Max(1f, e)), Sep);
            }
            Icon(new Rect(row.x + 38f * k - 36f * k, row.y + row.height * 0.5f - 36f * k, 72f * k, 72f * k), icon, sel ? Color.white : new Color(0.92f, 0.92f, 0.92f));

            float xt = row.x + 107f * k;
            float right = row.xMax - 14f * k;
            float tw = string.IsNullOrEmpty(tag) ? 0f : Width(Upper(tag), Fit(15f, k), false) + 12f * k;
            float vw = Width(value, Fit(21f, k), false);
            float groupL = right - tw - vw;
            Text(new Rect(xt, row.y + 26f * k - 15f * k, 340f * k, 30f * k), Upper(name), Fit(19f, k), sel ? White : new Color(0.84f, 0.86f, 0.86f), TextAnchor.MiddleLeft, sel);
            Text(new Rect(groupL, row.y + 33f * k - 16f * k, vw + 12f, 32f * k), value, Fit(21f, k), colValue, TextAnchor.MiddleLeft, false);
            if (tw > 0f) Text(new Rect(right - tw + 12f * k, row.y + 34f * k - 14f * k, tw + 12f, 28f * k), Upper(tag), Fit(15f, k), colTag, TextAnchor.MiddleLeft, false);
            float barR = groupL - 30f * k;
            Rect track = new Rect(xt, row.y + 48f * k - 4.5f * k, Mathf.Max(20f, barR - xt), 9f * k);
            Bar(track, frac, colBar);
        }

        /// <summary>Flat painted button (EXIT style), centered text; the selected one takes the game's petrol-blue.</summary>
        public static void ButtonPaint(Rect r, float k, string text, bool sel)
        {
            Paint(r, sel ? C(0, 56, 84) : C(32, 38, 40));
            Text(r, Upper(text), Fit(19f, k), sel ? White : new Color(0.88f, 0.9f, 0.9f), TextAnchor.MiddleCenter, false);
        }

        /// <summary>Width the text will take with the mod's font and tracking (for centering and sizing buttons).</summary>
        public static float TextWidth(string s, float size, bool bold) { return Width(s, size, bold); }

        public static float FontFit(float size, float k) { return Fit(size, k); }

        /// <summary>Key hints in a centered line just below a panel: (key, action) pairs.</summary>
        public static void KeysBelow(Rect panel, params string[] pairs)
        {
            float e = Sc;
            float total = 0f;
            for (int i = 0; i + 1 < pairs.Length; i += 2)
                total += 14f * e + Width(pairs[i], 15f, true) + 12f * e + Width(Upper(pairs[i + 1]), 15f, false) + 14f * e + 8f * e;
            float x = panel.x + (panel.width - total + 8f * e) * 0.5f;
            float y = panel.yMax + 10f * e;
            for (int i = 0; i + 1 < pairs.Length; i += 2) Key(ref x, y, pairs[i], pairs[i + 1]);
        }

        // ------------------------------------------------------------------ button prompts

        static void Key(ref float x, float y, string t, string action)
        {
            float e = Sc;
            string act = Upper(action);
            float kw = Width(t, 15f, true), aw = Width(act, 15f, false);
            float w = 14f * e + kw + 12f * e + aw + 14f * e;
            Rect b = new Rect(x, y, w, 30f * e);
            Fill(b, Button);
            Text(new Rect(b.x + 14f * e, b.y, kw + 8f, b.height), t, 15f, White, TextAnchor.MiddleLeft, true);
            Text(new Rect(b.x + 14f * e + kw + 12f * e, b.y, aw + 8f, b.height), act, 15f, Gray, TextAnchor.MiddleLeft, false);
            x += w + 8f * e;
        }

        /// <summary>Line of buttons at the bottom of the panel: (key, action) pairs, like the game's SOLTAR / ATRÁS buttons.</summary>
        public static void Footer(Rect panel, params string[] pairs)
        {
            float e = Sc;
            float y = panel.yMax - 44f * e;
            Fill(new Rect(panel.x + 22f * e, y - 10f * e, panel.width - 44f * e, Mathf.Max(1f, e)), Hair);
            float x = panel.x + 22f * e;
            for (int i = 0; i + 1 < pairs.Length; i += 2) Key(ref x, y, pairs[i], pairs[i + 1]);
        }

        // ------------------------------------------------------------------ on-screen messages

        /// <summary>Message at the bottom of the screen. 'alert' paints it red.</summary>
        public static void Notice(float W, float H, string text, bool alert)
        {
            Strip(W, H * 0.84f, text, alert ? Red : Accent, alert);
        }

        /// <summary>Hint about what is being looked at; if it starts with [X] it draws that key in a dark button.</summary>
        public static void Hint(float W, float y, string text)
        {
            Strip(W, y, text, Accent, false);
        }

        // White tracked text over a soft dark band (no box): the way the game shows its prompts and descriptions.
        static void Strip(float W, float y, string text, Color point, bool alert)
        {
            if (string.IsNullOrEmpty(text)) return;
            float e = Sc;
            string hotkey = null, rest = text;
            if (text.StartsWith("[") && text.IndexOf(']') > 1)
            {
                int i = text.IndexOf(']');
                hotkey = text.Substring(1, i - 1);
                rest = text.Substring(i + 1).Trim();
            }
            float size = 20f;
            float tw = Width(rest, size, false);
            float kh = 30f * e;
            float kw = hotkey != null ? Width(hotkey, 15f, true) + 24f * e : 0f;
            float gap = hotkey != null ? 14f * e : 0f;
            float lead = hotkey == null ? 16f * e : 0f;
            float contentW = lead + kw + gap + tw;
            float h = 50f * e;
            float bw = contentW + 220f * e;
            Rect b = new Rect((W - bw) * 0.5f, y, bw, h);
            Tex(b, band, new Color(0f, 0f, 0f, 0.66f));

            float x = b.x + (bw - contentW) * 0.5f;
            if (hotkey != null)
            {
                Rect k = new Rect(x, b.y + (h - kh) * 0.5f, kw, kh);
                Fill(k, Button);
                Text(k, hotkey, 15f, White, TextAnchor.MiddleCenter, true);
                x += kw + gap;
            }
            else
            {
                Fill(new Rect(x, b.y + h * 0.5f - 8f * e, 3f * e, 16f * e), point);
                x += lead;
            }
            Text(new Rect(x, b.y, tw + 10f, h), rest, size, alert ? Color.Lerp(White, Red, 0.55f) : White, TextAnchor.MiddleLeft, false);
        }

        /// <summary>Instruction box for the dashboard adjustment mode.</summary>
        public static void Calibration(float W, float H, string text)
        {
            float e = Sc;
            Rect r = new Rect(W * 0.5f - 480f * e, H * 0.05f, 960f * e, 104f * e);
            for (int i = 3; i >= 1; i--)
            {
                float g = i * 8f * e;
                Fill(new Rect(r.x - g, r.y - g * 0.6f, r.width + 2f * g, r.height + 2f * g), new Color(0f, 0f, 0f, 0.05f));
            }
            Fill(r, Backdrop);
            Tex(r, fadeTex, new Color(1f, 1f, 1f, 0.035f));
            Fill(new Rect(r.x + 22f * e, r.y + 16f * e, 4f * e, r.height - 32f * e), Yellow);
            Text(new Rect(r.x + 40f * e, r.y + 8f * e, r.width - 80f * e, r.height - 16f * e), text, 19f, White, TextAnchor.MiddleCenter, false);
        }
    }
